insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Liên hợp quốc chính thức ra đời ngày 24-10-1945. Mục đích hàng đầu của tổ chức là duy trì hòa bình và an ninh quốc tế.”', null, null, null, '[{"text":"Liên hợp quốc ra đời khi Chiến tranh thế giới thứ hai vừa kết thúc.","is_true":true,"explanation":"Chiến tranh thế giới thứ hai kết thúc tháng 9-1945; Liên hợp quốc chính thức ra đời ngày 24-10-1945."},{"text":"Hội nghị I-an-ta (2-1945) đã thỏa thuận về việc thành lập tổ chức Liên hợp quốc.","is_true":true,"explanation":"Một trong những quyết định của Hội nghị I-an-ta là thành lập tổ chức Liên hợp quốc để duy trì hòa bình, an ninh thế giới."},{"text":"Mọi nghị quyết của Đại hội đồng Liên hợp quốc đều bắt buộc các nước thành viên phải thi hành.","is_true":false,"explanation":"Nghị quyết của Đại hội đồng mang tính khuyến nghị; quyết định có tính ràng buộc thuộc về Hội đồng Bảo an."},{"text":"Việt Nam là thành viên của Liên hợp quốc ngay từ khi tổ chức này ra đời.","is_true":false,"explanation":"Đánh tráo thời gian: Việt Nam gia nhập Liên hợp quốc ngày 20-9-1977."}]'::jsonb, 'Câu kiểm tra bối cảnh ra đời, cơ cấu và quan hệ của Việt Nam với Liên hợp quốc.', 12, '1-lien-hop-quoc', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 1')
