values ('mcq', 'Sự kiện nào được coi là mở đầu Chiến tranh lạnh?', null, array['Liên Xô thử thành công bom nguyên tử (1949)', 'Mỹ đưa ra học thuyết Tơ-ru-man (3-1947)', 'Hội nghị I-an-ta được triệu tập (2-1945)', 'Tổ chức Hiệp ước Vác-sa-va ra đời (5-1955)'], 1, null, 'Học thuyết Tơ-ru-man (3-1947) đánh dấu sự khởi đầu của Chiến tranh lạnh. Hội nghị I-an-ta diễn ra trước đó; Hiệp ước Vác-sa-va và việc Liên Xô có bom nguyên tử diễn ra khi Chiến tranh lạnh đã bắt đầu.', 12, '2-trat-tu-the-gioi-trong-chien-tranh-lanh', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 2')
