insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Sau Chiến tranh thế giới thứ hai, trật tự thế giới hai cực I-an-ta được xác lập; Chiến tranh lạnh diễn ra từ năm 1947 đến năm 1989.”', null, null, null, '[{"text":"Đứng đầu hai cực trong trật tự I-an-ta là Liên Xô và Mỹ.","is_true":true,"explanation":"Trật tự hai cực I-an-ta do Liên Xô và Mỹ đứng đầu mỗi cực."},{"text":"Chiến tranh lạnh là cuộc chiến tranh trực tiếp bằng quân sự giữa Liên Xô và Mỹ.","is_true":false,"explanation":"Chiến tranh lạnh là sự đối đầu căng thẳng trên nhiều lĩnh vực; hai nước không trực tiếp đánh nhau bằng quân sự."},{"text":"NATO được thành lập trước Tổ chức Hiệp ước Vác-sa-va.","is_true":true,"explanation":"NATO ra đời năm 1949, Tổ chức Hiệp ước Vác-sa-va năm 1955."},{"text":"Trật tự hai cực I-an-ta sụp đổ ngay tại cuộc gặp Man-ta năm 1989.","is_true":false,"explanation":"Cuộc gặp Man-ta (12-1989) tuyên bố chấm dứt Chiến tranh lạnh; trật tự hai cực chỉ sụp đổ khi Liên Xô tan rã năm 1991."}]'::jsonb, 'Phân biệt trật tự hai cực với Chiến tranh lạnh và các mốc thời gian liên quan.', 12, '2-trat-tu-the-gioi-trong-chien-tranh-lanh', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 2')
