values ('mcq', 'Xu hướng phát triển của trật tự thế giới sau Chiến tranh lạnh là', null, array['hình thành trật tự đa cực, nhiều trung tâm', 'trở lại trật tự hai cực như trước', 'trật tự đơn cực ổn định do một nước chi phối hoàn toàn', 'không còn quan hệ giữa các cường quốc'], 0, null, 'Sau năm 1991, thế giới phát triển theo xu hướng đa cực với nhiều trung tâm quyền lực; Mỹ muốn xác lập trật tự đơn cực nhưng không thực hiện được.', 12, '3-trat-tu-the-gioi-sau-chien-tranh-lanh', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 3')
