values ('mcq', 'Mục tiêu của Cộng đồng Kinh tế ASEAN (AEC) là xây dựng ASEAN thành', null, array['một khu vực dùng chung một đồng tiền', 'một liên minh quân sự khu vực', 'một nhà nước liên bang chung', 'một thị trường và cơ sở sản xuất thống nhất'], 3, null, 'AEC hướng tới một thị trường và cơ sở sản xuất thống nhất, tự do lưu chuyển hàng hóa, dịch vụ, đầu tư. ASEAN không dùng đồng tiền chung, không phải liên minh quân sự và các nước vẫn giữ chủ quyền.', 12, '5-cong-dong-asean', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 5')
