insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Cộng đồng ASEAN được xây dựng dựa trên ba trụ cột: Cộng đồng Chính trị – An ninh, Cộng đồng Kinh tế và Cộng đồng Văn hóa – Xã hội.”', null, null, null, '[{"text":"Cộng đồng ASEAN chính thức được thành lập vào cuối năm 2015.","is_true":true,"explanation":"Ngày 31-12-2015, Cộng đồng ASEAN chính thức thành lập."},{"text":"Cộng đồng Kinh tế là một trong ba trụ cột của Cộng đồng ASEAN.","is_true":true,"explanation":"Thông tin có trong đề dẫn."},{"text":"Thành lập Cộng đồng ASEAN đồng nghĩa với việc các nước thành viên từ bỏ chủ quyền quốc gia.","is_true":false,"explanation":"ASEAN hợp tác trên cơ sở tôn trọng độc lập, chủ quyền của mỗi nước."},{"text":"Sau khi Cộng đồng ASEAN ra đời, ASEAN không còn phải đối mặt với thách thức nào.","is_true":false,"explanation":"Từ tuyệt đối: ASEAN vẫn còn nhiều thách thức như chênh lệch phát triển, tranh chấp chủ quyền, an ninh phi truyền thống."}]'::jsonb, 'Câu kiểm tra hiểu biết về Cộng đồng ASEAN và bản chất hợp tác của ASEAN.', 12, '5-cong-dong-asean', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 5')
on conflict (fingerprint) do nothing;

