insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Tuyên ngôn độc lập (2-9-1945) — đoạn kết', '“Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”', 'Hồ Chí Minh, Tuyên ngôn độc lập, đọc tại Quảng trường Ba Đình, Hà Nội, ngày 2-9-1945', '6-cach-mang-thang-tam-nam-1945'
where not exists (select 1 from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn kết' and body = '“Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”');
insert into public.exam_passages (title, body, source_citation, lesson_slug)
select 'Lời kêu gọi toàn quốc kháng chiến (12-1946)', '“Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.”', 'Hồ Chí Minh, Lời kêu gọi toàn quốc kháng chiến, ngày 19-12-1946', '7-khang-chien-chong-phap'
where not exists (select 1 from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946)' and body = '“Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.”');
insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Hội nghị toàn quốc của Đảng (8-1945) quyết định phát động Tổng khởi nghĩa giành chính quyền họp ở đâu?', null, array['Đình Bảng (Bắc Ninh)', 'Hương Cảng (Trung Quốc)', 'Tân Trào (Tuyên Quang)', 'Pác Bó (Cao Bằng)'], 2, null, 'Hội nghị toàn quốc của Đảng họp ở Tân Trào ngày 14 và 15-8-1945, quyết định phát động Tổng khởi nghĩa; tiếp đó Quốc dân Đại hội cũng họp ở Tân Trào (16-8-1945).', 12, '6-cach-mang-thang-tam-nam-1945', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6')
