insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Thời cơ “ngàn năm có một” để nhân dân Việt Nam tiến hành Tổng khởi nghĩa tháng Tám năm 1945 xuất hiện khi', null, array['Pháp đưa quân trở lại Đông Dương', 'Nhật Bản đầu hàng Đồng minh không điều kiện', 'Nhật đảo chính Pháp ở Đông Dương', 'quân Đồng minh vào giải giáp quân Nhật'], 1, null, 'Ngày 15-8-1945 Nhật đầu hàng Đồng minh, quân Nhật ở Đông Dương rệu rã, chính quyền tay sai hoang mang — trước khi quân Đồng minh vào. Đó là thời cơ để Tổng khởi nghĩa.', 12, '6-cach-mang-thang-tam-nam-1945', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6')
on conflict (fingerprint) do nothing;
