values ('mcq', 'Ngày 30-8-1945 diễn ra sự kiện nào?', null, array['Vua Bảo Đại thoái vị', 'Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi', 'Quốc dân Đại hội họp ở Tân Trào', 'Chủ tịch Hồ Chí Minh đọc Tuyên ngôn độc lập'], 0, null, 'Ngày 30-8-1945 vua Bảo Đại thoái vị, chế độ quân chủ chấm dứt. Hà Nội giành chính quyền ngày 19-8; Quốc dân Đại hội họp ngày 16-8; Tuyên ngôn độc lập được đọc ngày 2-9.', 12, '6-cach-mang-thang-tam-nam-1945', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 6')
