insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Từ ngày 14 đến ngày 28-8-1945, cuộc Tổng khởi nghĩa giành chính quyền diễn ra trong cả nước.”', null, null, null, '[{"text":"Khởi nghĩa giành chính quyền ở Hà Nội thắng lợi trước Huế và Sài Gòn.","is_true":true,"explanation":"Hà Nội ngày 19-8, Huế ngày 23-8, Sài Gòn ngày 25-8-1945."},{"text":"Bắc Giang, Hải Dương, Hà Tĩnh và Quảng Nam là những địa phương giành chính quyền ở tỉnh lị sớm nhất (18-8-1945).","is_true":true,"explanation":"Đây là bốn tỉnh giành chính quyền ở tỉnh lị sớm nhất trong cả nước."},{"text":"Cách mạng tháng Tám thắng lợi chủ yếu nhờ quân Đồng minh đánh đuổi phát xít Nhật ở Việt Nam.","is_true":false,"explanation":"Nhân dân Việt Nam tự lực giành chính quyền trước khi quân Đồng minh vào; Đồng minh chỉ tạo thời cơ khách quan khi đánh bại Nhật."},{"text":"Tổng khởi nghĩa nổ ra khi quân Nhật đang ở thế mạnh, chưa đầu hàng Đồng minh.","is_true":false,"explanation":"Tổng khởi nghĩa nổ ra sau khi Nhật đầu hàng Đồng minh (15-8-1945)."}]'::jsonb, 'Câu kiểm tra diễn biến và nguyên nhân thắng lợi của Cách mạng tháng Tám.', 12, '6-cach-mang-thang-tam-nam-1945', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 6')
