insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Đọc đoạn tư liệu và cho biết mỗi ý sau đúng hay sai.', (select id from public.exam_passages where title = 'Tuyên ngôn độc lập (2-9-1945) — đoạn kết' and body = '“Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do, độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.”' order by created_at limit 1), null, null, '[{"text":"Đoạn tư liệu khẳng định quyền hưởng tự do, độc lập của nước Việt Nam.","is_true":true,"explanation":"Câu đầu đoạn tư liệu nêu rõ điều này."},{"text":"Đoạn tư liệu thể hiện quyết tâm của toàn dân tộc giữ vững quyền tự do, độc lập.","is_true":true,"explanation":"“Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng…”."},{"text":"Theo đoạn tư liệu, Việt Nam sẽ giữ vững độc lập bằng cách dựa hoàn toàn vào nước ngoài.","is_true":false,"explanation":"Trái với tư liệu: dân tộc Việt Nam đem tất cả lực lượng của chính mình để giữ độc lập."},{"text":"Đoạn tư liệu ra đời sau khi cuộc kháng chiến chống thực dân Pháp thắng lợi.","is_true":false,"explanation":"Tuyên ngôn độc lập được đọc ngày 2-9-1945, trước cuộc kháng chiến chống Pháp."}]'::jsonb, 'Câu đọc hiểu tư liệu: phân biệt nội dung có trong tư liệu với suy diễn sai và bối cảnh thời gian.', 12, '6-cach-mang-thang-tam-nam-1945', null, 'van_dung', 'van_dung_kien_thuc', null, 'Tuyên ngôn độc lập (2-9-1945); SGK Lịch sử 12 (KNTT), Bài 6')
