insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Thắng lợi của chiến dịch Việt Bắc thu – đông năm 1947 đã làm phá sản chiến lược nào của thực dân Pháp?', null, array['Kế hoạch Rơ-ve', 'Kế hoạch Đờ Lát đơ Tát-xi-nhi', '“Đánh nhanh, thắng nhanh”', 'Kế hoạch Na-va'], 2, null, 'Thắng lợi Việt Bắc thu – đông 1947 làm phá sản chiến lược “đánh nhanh, thắng nhanh”, buộc Pháp chuyển sang đánh lâu dài.', 12, '7-khang-chien-chong-phap', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7')
