insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Năm 1953, Pháp và Mỹ đề ra kế hoạch quân sự nào nhằm giành thắng lợi quyết định trong vòng 18 tháng?', null, array['Kế hoạch Na-va', 'Kế hoạch Rơ-ve', 'Kế hoạch Xta-lây – Tay-lo', 'Kế hoạch Mác-san'], 0, null, 'Kế hoạch Na-va (1953) hi vọng trong 18 tháng giành thắng lợi quyết định. Kế hoạch Rơ-ve có từ năm 1949; Xta-lây – Tay-lo là kế hoạch của Mỹ ở miền Nam (1961); Mác-san là kế hoạch viện trợ Tây Âu.', 12, '7-khang-chien-chong-phap', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 7')
