insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Ngày 6-3-1946, Chủ tịch Hồ Chí Minh thay mặt Chính phủ kí với đại diện Chính phủ Pháp bản Hiệp định Sơ bộ.”', null, null, null, '[{"text":"Theo Hiệp định, Pháp công nhận Việt Nam là một quốc gia tự do, có chính phủ, nghị viện, quân đội và tài chính riêng.","is_true":true,"explanation":"Đây là nội dung chính của Hiệp định Sơ bộ."},{"text":"Việt Nam đồng ý cho 15 000 quân Pháp ra miền Bắc thay quân Trung Hoa Dân quốc.","is_true":true,"explanation":"Số quân này sẽ rút dần trong thời hạn 5 năm."},{"text":"Hiệp định Sơ bộ công nhận Việt Nam là một quốc gia độc lập hoàn toàn.","is_true":false,"explanation":"Hiệp định chỉ công nhận “quốc gia tự do”, chưa phải độc lập hoàn toàn."},{"text":"Sau khi kí Hiệp định Sơ bộ, chiến tranh giữa Việt Nam và Pháp chấm dứt hẳn.","is_true":false,"explanation":"Pháp tiếp tục lấn tới; cuối năm 1946 cuộc kháng chiến toàn quốc bùng nổ."}]'::jsonb, 'Câu kiểm tra nội dung và ý nghĩa của Hiệp định Sơ bộ 6-3-1946.', 12, '7-khang-chien-chong-phap', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 7')
