insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Đoạn tư liệu thể hiện rõ nhất điều gì?', (select id from public.exam_passages where title = 'Lời kêu gọi toàn quốc kháng chiến (12-1946)' and body = '“Chúng ta muốn hòa bình, chúng ta phải nhân nhượng. Nhưng chúng ta càng nhân nhượng, thực dân Pháp càng lấn tới, vì chúng quyết tâm cướp nước ta lần nữa! Không! Chúng ta thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ.”' order by created_at limit 1), array['Chủ trương hòa hoãn lâu dài với thực dân Pháp', 'Mong muốn dựa vào nước ngoài để giữ hòa bình', 'Kế hoạch tổng tiến công kết thúc chiến tranh', 'Quyết tâm bảo vệ độc lập, không chịu mất nước'], 3, null, '“Thà hy sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ” thể hiện quyết tâm bảo vệ độc lập. Tư liệu nói đã nhân nhượng nhưng Pháp lấn tới, nên không còn hòa hoãn; tư liệu không nói tới dựa vào nước ngoài hay kế hoạch tổng tiến công.', 12, '7-khang-chien-chong-phap', null, 'van_dung', 'van_dung_kien_thuc', null, 'Lời kêu gọi toàn quốc kháng chiến (19-12-1946); SGK Lịch sử 12 (KNTT), Bài 7')
