values ('mcq', 'Hội Việt Nam Cách mạng Thanh niên được Nguyễn Ái Quốc thành lập năm 1925 tại', null, array['Quảng Châu (Trung Quốc)', 'Pa-ri (Pháp)', 'Mát-xcơ-va (Liên Xô)', 'Băng Cốc (Thái Lan)'], 0, null, 'Tháng 6-1925, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu (Trung Quốc).', 12, '12-doi-ngoai-dau-the-ki-xx-den-1945', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 12')
