insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Từ đầu thế kỉ XX đến năm 1945, nhiều nhà yêu nước Việt Nam đã hoạt động ở nước ngoài để tìm kiếm sự ủng hộ cho cuộc đấu tranh giành độc lập.”', null, null, null, '[{"text":"Hoạt động đối ngoại của Phan Bội Châu gắn với phong trào Đông du.","is_true":true,"explanation":"Phan Bội Châu khởi xướng phong trào Đông du (1905 – 1908)."},{"text":"Phan Châu Trinh chủ trương dựa vào Nhật Bản để bạo động đánh Pháp.","is_true":false,"explanation":"Đánh tráo chủ thể: Phan Châu Trinh chủ trương cải cách, dựa vào Pháp để đòi canh tân; dựa vào Nhật là chủ trương của Phan Bội Châu."},{"text":"Năm 1920, tại Đại hội Tua, Nguyễn Ái Quốc tán thành việc gia nhập Quốc tế Cộng sản.","is_true":true,"explanation":"Tháng 12-1920, Nguyễn Ái Quốc bỏ phiếu tán thành gia nhập Quốc tế thứ ba."},{"text":"Hoạt động đối ngoại của Nguyễn Ái Quốc trong thời kì này chỉ diễn ra ở Pháp.","is_true":false,"explanation":"Từ tuyệt đối “chỉ”: Người còn hoạt động ở Liên Xô, Trung Quốc, Thái Lan…"}]'::jsonb, 'Câu kiểm tra hoạt động đối ngoại của các nhà yêu nước đầu thế kỉ XX.', 12, '12-doi-ngoai-dau-the-ki-xx-den-1945', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 12')
