insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Đầu năm 1950, những nước nào công nhận và đặt quan hệ ngoại giao với nước Việt Nam Dân chủ Cộng hòa?', null, array['Mỹ, Anh, Pháp và các nước Tây Âu', 'Các nước sáng lập Hiệp hội các quốc gia Đông Nam Á', 'Nhật Bản, Hàn Quốc và các nước Đông Bắc Á', 'Trung Quốc, Liên Xô và các nước dân chủ nhân dân'], 3, null, 'Đầu năm 1950, Trung Quốc, Liên Xô và các nước dân chủ nhân dân lần lượt công nhận và đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa — phá thế bao vây, cô lập.', 12, '13-doi-ngoai-trong-khang-chien-1945-1975', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 13')
on conflict (fingerprint) do nothing;
insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Người thay mặt Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam kí Hiệp định Pa-ri năm 1973 là', null, array['Xuân Thủy', 'Phạm Văn Đồng', 'Nguyễn Thị Bình', 'Lê Đức Thọ'], 2, null, 'Bộ trưởng Ngoại giao Nguyễn Thị Bình thay mặt Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam kí Hiệp định Pa-ri. Lê Đức Thọ là cố vấn đặc biệt, Xuân Thủy là trưởng đoàn của Việt Nam Dân chủ Cộng hòa trong đàm phán.', 12, '13-doi-ngoai-trong-khang-chien-1945-1975', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 13')
