insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Trong hai cuộc kháng chiến (1945 – 1975), mặt trận ngoại giao góp phần quan trọng vào thắng lợi chung của dân tộc.”', null, null, null, '[{"text":"Việc kí Hiệp định Sơ bộ (6-3-1946) thể hiện sách lược “hòa để tiến”.","is_true":true,"explanation":"Hòa hoãn với Pháp để đẩy quân Trung Hoa Dân quốc về nước, tranh thủ thời gian chuẩn bị lực lượng."},{"text":"Hội nghị Giơ-ne-vơ năm 1954 bàn về việc chấm dứt chiến tranh ở Đông Dương.","is_true":true,"explanation":"Hội nghị Giơ-ne-vơ (1954) bàn về vấn đề Triều Tiên và lập lại hòa bình ở Đông Dương."},{"text":"Hiệp định Pa-ri được kí kết trước Hiệp định Giơ-ne-vơ.","is_true":false,"explanation":"Hiệp định Giơ-ne-vơ năm 1954, Hiệp định Pa-ri năm 1973."},{"text":"Trong kháng chiến chống Mỹ, Việt Nam không nhận được sự ủng hộ của nhân dân thế giới.","is_true":false,"explanation":"Việt Nam nhận được sự ủng hộ rộng rãi của các nước xã hội chủ nghĩa và phong trào phản chiến, nhân dân tiến bộ thế giới, kể cả nhân dân Mỹ."}]'::jsonb, 'Câu kiểm tra vai trò của mặt trận ngoại giao trong kháng chiến.', 12, '13-doi-ngoai-trong-khang-chien-1945-1975', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 13')
