values ('mcq', 'Việt Nam trở thành thành viên của Diễn đàn Hợp tác kinh tế châu Á – Thái Bình Dương (APEC) năm nào?', null, array['1977', '1998', '1995', '2007'], 1, null, 'Việt Nam gia nhập APEC tháng 11-1998. Năm 1995 gia nhập ASEAN, năm 2007 gia nhập WTO, năm 1977 gia nhập Liên hợp quốc.', 12, '14-doi-ngoai-tu-nam-1975-den-nay', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 14')
