insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Năm 1991, Việt Nam bình thường hóa quan hệ với quốc gia nào?', null, array['Trung Quốc', 'Hoa Kỳ', 'Hàn Quốc', 'Ô-xtrây-li-a'], 0, null, 'Tháng 11-1991, Việt Nam và Trung Quốc bình thường hóa quan hệ. Việt Nam bình thường hóa quan hệ với Hoa Kỳ năm 1995, thiết lập quan hệ ngoại giao với Hàn Quốc năm 1992.', 12, '14-doi-ngoai-tu-nam-1975-den-nay', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 14')
