insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Từ năm 1986, Việt Nam thực hiện chính sách đối ngoại rộng mở, đa phương hóa, đa dạng hóa quan hệ quốc tế.”', null, null, null, '[{"text":"Năm 1995, Việt Nam bình thường hóa quan hệ với Hoa Kỳ và gia nhập ASEAN.","is_true":true,"explanation":"Hai sự kiện đối ngoại lớn của năm 1995."},{"text":"Việt Nam trở thành thành viên Tổ chức Thương mại thế giới (WTO) năm 2007.","is_true":true,"explanation":"Ngày 11-1-2007 Việt Nam chính thức là thành viên WTO."},{"text":"Năm 2017, Việt Nam đăng cai Hội nghị cấp cao APEC tại Hà Nội.","is_true":false,"explanation":"Năm 2017 Hội nghị cấp cao APEC tổ chức tại Đà Nẵng; Hà Nội đăng cai năm 2006."},{"text":"Chính sách đối ngoại thời kì Đổi mới chủ trương chỉ quan hệ với các nước xã hội chủ nghĩa.","is_true":false,"explanation":"Trái với chủ trương đa phương hóa, đa dạng hóa: Việt Nam mở rộng quan hệ với mọi nước."}]'::jsonb, 'Câu kiểm tra thành tựu đối ngoại của Việt Nam từ năm 1986.', 12, '14-doi-ngoai-tu-nam-1975-den-nay', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 14')
