values ('mcq', 'Chủ tịch Hồ Chí Minh sinh ngày 19-5-1890 tại', null, array['bản Pác Bó, huyện Hà Quảng, tỉnh Cao Bằng', 'xã Tân Trào, huyện Sơn Dương, tỉnh Tuyên Quang', 'bến cảng Nhà Rồng, thành phố Sài Gòn', 'làng Kim Liên, huyện Nam Đàn, tỉnh Nghệ An'], 3, null, 'Người sinh ở làng Kim Liên (làng Sen), huyện Nam Đàn, tỉnh Nghệ An. Pác Bó, Tân Trào, bến Nhà Rồng gắn với các giai đoạn hoạt động sau này của Người.', 12, '15-khai-quat-cuoc-doi-va-su-nghiep-ho-chi-minh', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 15')
