insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('mcq', 'Tên khai sinh của Chủ tịch Hồ Chí Minh là', null, array['Nguyễn Ái Quốc', 'Lý Thụy', 'Nguyễn Sinh Cung', 'Nguyễn Tất Thành'], 2, null, 'Tên khai sinh là Nguyễn Sinh Cung; khi đi học đổi tên là Nguyễn Tất Thành; Nguyễn Ái Quốc là tên dùng từ năm 1919; Lý Thụy là bí danh khi hoạt động ở Trung Quốc.', 12, '15-khai-quat-cuoc-doi-va-su-nghiep-ho-chi-minh', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 15')
