values ('mcq', 'Mặt trận Việt Minh được thành lập năm 1941 theo đề nghị của ai?', null, array['Nguyễn Ái Quốc', 'Trường Chinh', 'Võ Nguyên Giáp', 'Trần Phú'], 0, null, 'Hội nghị Trung ương 8 (5-1941) do Nguyễn Ái Quốc chủ trì quyết định thành lập Mặt trận Việt Nam độc lập đồng minh (Việt Minh) theo đề nghị của Người.', 12, '16-ho-chi-minh-anh-hung-giai-phong-dan-toc', null, 'nhan_biet', 'tim_hieu_lich_su', null, 'SGK Lịch sử 12 (KNTT), Bài 16')
