insert into public.exam_items (kind, stem, passage_id, choices, correct_index, statements, explanation, grade, lesson_slug, topic_tag, level, competency, event_id, source_note)
values ('true_false', 'Cho thông tin: “Đầu năm 1941, Nguyễn Ái Quốc về nước trực tiếp lãnh đạo cách mạng Việt Nam.”', null, null, null, '[{"text":"Tháng 5-1941, Nguyễn Ái Quốc chủ trì Hội nghị lần thứ 8 Ban Chấp hành Trung ương Đảng.","is_true":true,"explanation":"Hội nghị họp tại Pác Bó (Cao Bằng)."},{"text":"Hội nghị Trung ương 8 đặt nhiệm vụ giải phóng dân tộc lên hàng đầu.","is_true":true,"explanation":"Đây là điểm cốt lõi của Hội nghị Trung ương 8 (5-1941)."},{"text":"Mặt trận Việt Minh được thành lập sau thắng lợi của Cách mạng tháng Tám.","is_true":false,"explanation":"Mặt trận Việt Minh thành lập ngày 19-5-1941, trước Cách mạng tháng Tám."},{"text":"Hội nghị Trung ương 8 chủ trương tạm gác lại nhiệm vụ đánh đuổi phát xít Nhật để tập trung chống Pháp.","is_true":false,"explanation":"Hội nghị chủ trương đánh đuổi cả Pháp và Nhật, giành độc lập dân tộc."}]'::jsonb, 'Câu kiểm tra vai trò của Nguyễn Ái Quốc trong chuẩn bị Cách mạng tháng Tám.', 12, '16-ho-chi-minh-anh-hung-giai-phong-dan-toc', null, 'thong_hieu', 'nhan_thuc_tu_duy', null, 'SGK Lịch sử 12 (KNTT), Bài 16')
